GUIDE = {'overview': 'Interviewing Skills is the IEP version of Job Seeking Skills, for members classified under IDEA. You submit a pre-judged personal statement and resume, then do a 5-minute interview. You must also submit an Accommodation Form by May 15 or lose 35 points.', 'facts': [('Round One', 'Personal statement + resume (one PDF, May 15)'), ('Round Two', '5-minute interview'), ('Eligibility', 'Members classified under IDEA (IEP)'), ('Divisions', 'Secondary')], 'rounds': [('Round One: personal statement and resume (pre-judged)', ['Confirm you are classified under IDEA (Section 504 is not eligible) and submit the Accommodation Form by your state deadline and for ILC by May 15. Missing it costs 35 points.', 'Choose a real health-related job, internship, scholarship, or educational opportunity you are (or are being) trained for.', "Write a Personal Statement: your story, an invitation to get to know you, and a snapshot of who you are. Include things that aren't on your resume.", "Page 1: a title page with the event name, your name, HOSA division, chapter #, school, Chartered Association, and the opportunity you're applying for.", 'Pages 2–3: the statement. One-sided, typed, two pages max, 12 pt Arial, double-spaced, 1-inch margins. Running header with last name and event name on the top left, page number on the top right.', 'Write a one-page resume with education, work, responsibilities, and experiences relevant to the opportunity. Everything must be factual.', "Combine the statement and resume into ONE PDF and upload to the HOSA Digital Upload System by May 15 at midnight EST. If it isn't one PDF, it gets no points. Upload again for ILC even if you uploaded for state.", 'Only competitors who upload advance to the interview.']), ('Round Two: interview', ['Report at your appointment time. No materials are allowed in the interview, not even a copy of your resume.', 'Handshakes with judges are allowed and encouraged at the start and end.', 'The interview lasts up to 5 minutes, with a card at 1 minute remaining.', "The first two questions always ask you to explain the opportunity you're applying for and the skills you'd bring to it.", "The other questions are secret. Don't discuss them until the event is over.", 'Your final score is the pre-judged documents plus the interview.'])], 'rubrics': [{'title': 'Round One: personal statement and resume', 'total': 105, 'sections': [('Personal statement', [('Spelling and grammar', 5), ('Length (2 pages + title page)', 5), ('Formatting', 5), ('Introduction', 10), ('Ability to tell a story', 10), ('Snapshot of the competitor', 10), ('Conclusion', 10)]), ('Resume', [('Spelling and grammar', 5), ('Length (1 page)', 5), ('Content', 20), ('Creativity', 20)])]}, {'title': 'Round Two: interview', 'total': 80, 'sections': [('Interview', [('Introduction and first impression', 15), ('Answers: volunteers information, responds to every question, relates strengths, sounds professional', 15), ('Confidence, maturity, enthusiasm', 10), ('Knowledge of the position applied for', 10), ('Closing', 10), ('Diction, pronunciation, and grammar', 10), ('Eye contact, poise, and posture', 10)])]}], 'tips': ["Pick an opportunity you know well. 'Knowledge of the position' is 10 points, and the first two questions are about it.", "Have a crisp 30-second answer ready for 'Tell us about the position' and 'What skills would you bring?'", "Open the statement with a real story or turning point, not 'My name is...'.", 'Make the resume visually clean and creative (20 points). Use clear headings, bullet points, and action verbs.', 'Practice with mock interviews using common questions: strengths and weaknesses, teamwork, handling conflict, why health care.', 'Use the STAR method for experience questions: Situation, Task, Action, Result.', 'Prepare a strong close: thank the judges, restate your interest, and offer a firm handshake.'], 'mistakes': ['Uploading two separate files instead of one combined PDF.', 'Statement longer than 2 pages or missing the running header and page numbers.', 'Repeating the resume in the statement instead of telling your story.', 'Bringing your resume into the interview. No materials are allowed.', 'Vague answers about the position you chose.', 'Forgetting to close: no thank you, no handshake, no final statement.', 'Missing the Accommodation Form deadline (35-point penalty).'], 'checklist': ['Confirm IDEA/IEP eligibility and submit the Accommodation Form by May 15', 'Choose a real health job, internship, or scholarship to apply for', 'Draft the personal statement as a story', 'Format: title page + 2 pages, Arial 12, double-spaced, header and page numbers', 'Write a one-page, factual resume tailored to the opportunity', 'Proofread both documents with an adult', 'Combine into ONE PDF and upload by May 15', 'Prepare answers about the position and your skills', 'Do at least two mock interviews', 'Practice a firm handshake, eye contact, and a strong close', 'Pack photo ID and business attire or HOSA uniform']}
